function padOdsOptions($options){
 if(array_diff(array_keys($options),['sheet','header','formulas']))padFormatFail(0,'unknown ODS option');$header=$options['header']??'first';$formulas=$options['formulas']??'reject';if(!in_array($header,['first','none'],TRUE)||!in_array($formulas,['reject','cached','text'],TRUE))padFormatFail(0,'header is first/none; formulas is reject/cached/text');if(!class_exists('ZipArchive')||!class_exists('DOMDocument'))padFormatFail(0,'ODS requires ZIP and DOM extensions');return [$header,$formulas];
