function padOdsZip($bytes=NULL,$parts=NULL){
 $file=tempnam(sys_get_temp_dir(),'pad-ods-');if($file===FALSE)padFormatFail(0,'cannot allocate ODS temporary file');$zip=new ZipArchive();$opened=FALSE;
