 if($zip->getFromName('mimetype')!==padOdsMime)padFormatFail(0,'ZIP is not an ODS spreadsheet');$stat=$zip->statName('content.xml');if(!$stat||$stat['size']>8388608)padFormatFail(0,'missing or oversized ODS content.xml');$xml=$zip->getFromName('content.xml');if($xml===FALSE||strlen($xml)!==$stat['size'])padFormatFail(0,'cannot read complete ODS content.xml');return $xml;
 }finally{if($opened)$zip->close();@unlink($file);}
}
function padOdsRepeat($node,$attribute,$max){$raw=$node->hasAttributeNS(padOdsTable,$attribute)?$node->getAttributeNS(padOdsTable,$attribute):'1';if(!preg_match('/^[1-9][0-9]*$/D',$raw)||(float)$raw>$max)padFormatFail($node->getLineNo(),'invalid or excessive '.$attribute);return (int)$raw;}
function padOdsTextValue($node){
 $out='';foreach($node->childNodes as $child){if($child instanceof DOMText)$out.=$child->data;elseif($child instanceof DOMElement){if($child->namespaceURI!==padOdsText)padFormatFail($child->getLineNo(),'unsupported non-text cell content');if($child->localName==='s'){$raw=$child->getAttributeNS(padOdsText,'c')?:'1';if(!preg_match('/^[1-9][0-9]*$/D',$raw)||(float)$raw>10000)padFormatFail($child->getLineNo(),'excessive repeated spaces');$out.=str_repeat(' ',(int)$raw);}elseif($child->localName==='tab')$out.="\t";elseif($child->localName==='line-break')$out.="\n";else $out.=padOdsTextValue($child);}if(strlen($out)>65536)padFormatFail($node->getLineNo(),'cell text exceeds 65536 bytes');}return $out;
}
function padOdsCell($cell,$formulas){
 if($cell->localName==='covered-table-cell'||$cell->hasAttributeNS(padOdsTable,'number-columns-spanned')||$cell->hasAttributeNS(padOdsTable,'number-rows-spanned'))padFormatFail($cell->getLineNo(),'merged cells are outside the scalar ODS subset');
