 if($type==='time'){$raw=$get('time-value');if(!preg_match('/^-?P(?=\d|T\d)(?:\d+D)?(?:T(?:\d+H)?(?:\d+M)?(?:\d+(?:\.\d+)?S)?)?$/D',$raw))padFormatFail($cell->getLineNo(),'invalid ISO duration cell');return $raw;}
 if($type==='string'){if($cell->hasAttributeNS(padOdsOffice,'string-value'))return $get('string-value');$paragraphs=[];foreach($cell->childNodes as $child)if($child instanceof DOMElement){if($child->namespaceURI!==padOdsText||$child->localName!=='p')padFormatFail($cell->getLineNo(),'unsupported cell content');$paragraphs[]=padOdsTextValue($child);}return implode("\n",$paragraphs);}
 padFormatFail($cell->getLineNo(),'unsupported scalar cell type '.$type);
}
function padOdsRead($bytes,$options){
 [$header,$formulas]=padOdsOptions($options);$xml=padOdsZip($bytes);if(preg_match('/<!DOCTYPE|<!ENTITY/i',$xml))padFormatFail(0,'ODS XML declarations are forbidden');$old=libxml_use_internal_errors(TRUE);try{$dom=new DOMDocument();if(!$dom->loadXML($xml,LIBXML_NONET|LIBXML_COMPACT)){ $errors=libxml_get_errors();padFormatFail($errors[0]->line??0,'malformed ODS content.xml');}}finally{libxml_clear_errors();libxml_use_internal_errors($old);}
 $stack=[[$dom->documentElement,0]];$nodes=0;while($stack){[$node,$depth]=array_pop($stack);if(++$nodes>200000||$depth>64)padFormatFail(0,'ODS XML node/depth limit');foreach($node->childNodes as $child)if($child instanceof DOMElement)$stack[]=[$child,$depth+1];}
 $xpath=new DOMXPath($dom);$xpath->registerNamespace('office',padOdsOffice);$xpath->registerNamespace('table',padOdsTable);$tables=$xpath->query('/office:document-content/office:body/office:spreadsheet/table:table');$selector=$options['sheet']??0;$table=NULL;if(is_int($selector)&&$selector>=0)$table=$tables->item($selector);elseif(is_string($selector)&&$selector!==''&&strlen($selector)<=128)foreach($tables as $candidate)if($candidate->getAttributeNS(padOdsTable,'name')===$selector){if($table)padFormatFail(0,'ambiguous ODS sheet name');$table=$candidate;}if(!$table)padFormatFail(0,'selected ODS sheet not found');
 if($xpath->query('.//table:table',$table)->length)padFormatFail($table->getLineNo(),'nested spreadsheet tables are unsupported');$rows=[];$width=0;$cells=0;$textBytes=0;foreach($xpath->query('.//table:table-row',$table) as $row){$repeat=padOdsRepeat($row,'number-rows-repeated',10000);if(count($rows)+$repeat>10000)padFormatFail($row->getLineNo(),'ODS exceeds 10000 rows');$values=[];foreach($xpath->query('./table:table-cell|./table:covered-table-cell',$row) as $cell){$copies=padOdsRepeat($cell,'number-columns-repeated',256);if(count($values)+$copies>256)padFormatFail($cell->getLineNo(),'ODS exceeds 256 columns');$value=padOdsCell($cell,$formulas);if(is_string($value)&&(strlen($value)>65536||($textBytes+=strlen($value)*$copies*$repeat)>8388608))padFormatFail($cell->getLineNo(),'expanded ODS text exceeds scalar/8 MiB limit');for($i=0;$i<$copies;$i++)$values[]=$value;}$width=max($width,count($values));$cells+=count($values)*$repeat;if($cells>100000)padFormatFail($row->getLineNo(),'ODS exceeds 100000 scalar cells');for($i=0;$i<$repeat;$i++)$rows[]=$values;}
 if(!$width||!$rows)return [];if(count($rows)*$width>100000)padFormatFail(0,'ODS rectangle exceeds 100000 cells');$rows=array_map(fn($row)=>array_pad($row,$width,NULL),$rows);$names=$header==='first'?array_map(fn($v)=>is_scalar($v)?(string)$v:'',array_shift($rows)):array_map(fn($i)=>'column'.$i,range(1,$width));if(in_array('',$names,TRUE)||count(array_unique($names,SORT_STRING))!==count($names))padFormatFail(0,'ODS header must contain unique nonempty scalar names');return array_map(fn($row)=>array_combine($names,$row),$rows);
