function padOdsWrite($rows,$options){
 [$header,]=padOdsOptions($options);$name=$options['sheet']??'Sheet1';if(!is_string($name)||$name===''||strlen($name)>128||(!mb_check_encoding($name,'UTF-8')||preg_match('/[\x00-\x1F\x{FFFE}\x{FFFF}]/u',$name)))padFormatFail(0,'sheet name requires 1..128 UTF-8 bytes');if(count($rows)>10000)padFormatFail(0,'ODS exceeds 10000 rows');$columns=padFormatColumns($rows);if(count($columns)>256||(count($rows)+($header==='first'?1:0))*count($columns)>100000)padFormatFail(0,'ODS cell/column limit exceeded');$all=$header==='first'&&$columns?[array_values($columns)]:[];foreach($rows as $row)$all[]=array_map(fn($c)=>$row[$c]??NULL,$columns);if(count($all)>10000)padFormatFail(0,'ODS exceeds 10000 rows including header');$body='';
 foreach($all as $row){$body.='<table:table-row>';foreach($row as $value){if($value===NULL)$body.='<table:table-cell/>';elseif(is_bool($value))$body.='<table:table-cell office:value-type="boolean" office:boolean-value="'.($value?'true':'false').'"/>';elseif(is_int($value)||is_float($value)){if(!is_finite((float)$value))padFormatFail(0,'ODS numbers must be finite');$body.='<table:table-cell office:value-type="float" office:value="'.padFormatXml(json_encode($value,JSON_PRESERVE_ZERO_FRACTION)).'"/>';}elseif(is_string($value)&&strlen($value)<=65536&&mb_check_encoding($value,'UTF-8')&&!preg_match('/[\x00-\x08\x0B\x0C\x0E-\x1F\x{FFFE}\x{FFFF}]/u',$value)){$body.='<table:table-cell office:value-type="string" office:string-value="'.str_replace(["\t","\n","\r"],['&#9;','&#10;','&#13;'],padFormatXml($value)).'"><text:p>'.padFormatXml($value).'</text:p></table:table-cell>';}else padFormatFail(0,'ODS supports bounded scalar cells only');} $body.='</table:table-row>';if(strlen($body)>8000000)padFormatFail(0,'ODS XML exceeds 8 MiB');}
 $xml='<?xml version="1.0" encoding="UTF-8"?><office:document-content xmlns:office="'.padOdsOffice.'" xmlns:table="'.padOdsTable.'" xmlns:text="'.padOdsText.'" office:version="1.3"><office:body><office:spreadsheet><table:table table:name="'.padFormatXml($name).'">'.$body.'</table:table></office:spreadsheet></office:body></office:document-content>';
 $manifest='<?xml version="1.0" encoding="UTF-8"?><manifest:manifest xmlns:manifest="urn:oasis:names:tc:opendocument:xmlns:manifest:1.0" manifest:version="1.3"><manifest:file-entry manifest:full-path="/" manifest:version="1.3" manifest:media-type="'.padOdsMime.'"/><manifest:file-entry manifest:full-path="content.xml" manifest:media-type="text/xml"/></manifest:manifest>';
